CREATE COLUMN TABLE "TEST_AP"."OQAG" ("AUTHGRPID" INTEGER CS_INT NOT NULL , "AUTHGRPCD" NVARCHAR(50) NOT NULL , "AUTHGRPN" NVARCHAR(254) NOT NULL , "LogInstanc" INTEGER CS_INT DEFAULT 0, "UserSign" SMALLINT CS_INT, "UserSign2" SMALLINT CS_INT, "UpdateDate" LONGDATE CS_LONGDATE, "CreateDate" LONGDATE CS_LONGDATE, "Deleted" NVARCHAR(1) DEFAULT 'N', "SnapShotID" INTEGER CS_INT DEFAULT 0, PRIMARY KEY ("AUTHGRPID")) UNLOAD PRIORITY 5  AUTO MERGE ;
CREATE UNIQUE INDEX "OQAG_NAME_KEY" ON "TEST_AP"."OQAG" ( "AUTHGRPCD" ASC );
CREATE UNIQUE INDEX "OQAG_DES_KEY" ON "TEST_AP"."OQAG" ( "AUTHGRPN" ASC )